from lfx.custom import Component
from lfx.io import HandleInput, Output
from lfx.schema import Data
from lfx.schema.dataframe import DataFrame
from lfx.schema.message import Message


class CycleLoopComponent(Component):
    display_name = "Cycle Loop"
    description = "Iterates by sending one item per pass through a graph cycle and collecting what comes back."
    icon = "infinity"

    inputs = [
        HandleInput(name="data", display_name="Data", input_types=["DataFrame", "Data"]),
    ]

    outputs = [
        Output(display_name="Item", name="item", method="item_output", allows_loop=True, loop_types=["Message"]),
        Output(display_name="Done", name="done", method="done_output"),
    ]

    def initialize_data(self) -> None:
        if self.ctx.get(f"{self._id}_initialized", False):
            return
        data = self.data
        if isinstance(data, DataFrame):
            data = data.to_data_list()
        elif isinstance(data, Data):
            data = [data]
        self.update_ctx(
            {
                f"{self._id}_data": data,
                f"{self._id}_index": 0,
                f"{self._id}_aggregated": [],
                f"{self._id}_initialized": True,
            }
        )

    def evaluate_stop_loop(self) -> bool:
        current_index = self.ctx.get(f"{self._id}_index", 0)
        return current_index > len(self.ctx.get(f"{self._id}_data", []))

    def item_output(self) -> Data:
        self.initialize_data()
        current_item = Data(text="")
        if self.evaluate_stop_loop():
            self.stop("item")
        else:
            data_list = self.ctx.get(f"{self._id}_data", [])
            current_index = self.ctx.get(f"{self._id}_index", 0)
            if current_index < len(data_list):
                current_item = data_list[current_index]
            self.aggregated_output()
            self.update_ctx({f"{self._id}_index": current_index + 1})
        return current_item

    def done_output(self) -> Message:
        self.initialize_data()
        if self.evaluate_stop_loop():
            self.stop("item")
            self.start("done")
            aggregated = self.ctx.get(f"{self._id}_aggregated", [])
            return Message(text=" | ".join(getattr(item, "text", str(item)) for item in aggregated))
        self.stop("done")
        return Message(text="")

    def aggregated_output(self) -> list:
        self.initialize_data()
        data_list = self.ctx.get(f"{self._id}_data", [])
        aggregated = self.ctx.get(f"{self._id}_aggregated", [])
        if self.item is not None and not isinstance(self.item, str) and len(aggregated) <= len(data_list):
            aggregated.append(self.item)
            self.update_ctx({f"{self._id}_aggregated": aggregated})
        return aggregated

